insert into public.genres (id, slug, name, clinical_name, description, sort) values
  ('00000000-0000-4000-8000-000000000001', 'climb', 'Climb', 'Active-Assisted Range of Motion', 'Walk your hands up the hexagons, using the board as a guide as you reach.', 1),
  ('00000000-0000-4000-8000-000000000002', 'strengthen', 'Strengthen', 'Strengthening', 'Clip a band to an anchor point and push, pull or press against it.', 2),
  ('00000000-0000-4000-8000-000000000003', 'stretch', 'Stretch', 'Stretching', 'Settle into a gentle stretch with a band or handhold at the height you choose.', 3),
  ('00000000-0000-4000-8000-000000000004', 'loosen', 'Loosen', 'Joint Mobilizations', 'Slow, guided joint movements. Dr. Eric is preparing these.', 4),
  ('00000000-0000-4000-8000-000000000005', 'steady', 'Steady', 'Balance Training', 'Practice standing and stepping with the handrails within reach.', 5),
  ('00000000-0000-4000-8000-000000000006', 'rise', 'Rise', 'Transfer Training', 'Practice sit-to-stand, reaching and stepping with the rails for support.', 6)
insert into public.movements (id, genre_id, name, slug, level, board_models, needs_band, needs_handrail, needs_chair, default_anchor, video_url, poster_url, cues, safety_note, default_sets, default_reps, default_hold_seconds, reviewed_by_eric) values
  ('10000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001', '[DRAFT] Climb — standing wall climb', 'draft-climb-standing-wall-climb', 2, array['vb', 'xt']::text[], false, false, false, '{"section":3,"row":6,"col":2}'::jsonb, null, null, array['Stand facing the board, feet hip-width apart.', 'Walk your fingers up one hexagon at a time toward the marked hexagon.', 'Pause where it feels like a comfortable reach, then walk back down.']::text[], 'Move slowly and stay within a comfortable range. Stop if you feel sharp pain, and check with your therapist.', 2, 10, 5, false),
  ('10000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000001', '[DRAFT] Climb — side wall walk', 'draft-climb-side-wall-walk', 2, array['vb', 'xt']::text[], false, false, false, '{"section":3,"row":2,"col":1}'::jsonb, null, null, array['Stand side-on to the board, an arm''s length away.', 'Walk the fingers of the near hand up the hexagons.', 'Pause at the marked hexagon or lower, then walk back down and turn around.']::text[], 'Keep your shoulders relaxed. Stop if you feel sharp pain, and check with your therapist.', 2, 8, 5, false),
  ('10000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000001', '[DRAFT] Climb — seated wall walk', 'draft-climb-seated-wall-walk', 1, array['vb', 'xt']::text[], false, false, true, '{"section":2,"row":14,"col":2}'::jsonb, null, null, array['Sit tall in a sturdy chair facing the board, close enough to touch it.', 'Walk your fingers up one hexagon at a time.', 'Pause at the highest hexagon that feels comfortable, then walk back down.']::text[], 'Use a chair that will not slide. Stop if you feel sharp pain, and check with your therapist.', 2, 8, 3, false),
  ('10000000-0000-4000-8000-000000000004', '00000000-0000-4000-8000-000000000003', '[DRAFT] Stretch — overhead band reach', 'draft-stretch-overhead-band-reach', 1, array['vb', 'xt']::text[], true, false, false, '{"section":3,"row":16,"col":2}'::jsonb, null, null, array['Clip a band high on the board. You can stand or sit.', 'Hold the loop and let it draw your arm gently upward.', 'Breathe slowly while you hold, then switch arms.']::text[], 'Before each set, check the band for nicks or tears and make sure the carabiner is closed on the anchor. Stop if you feel sharp pain, and check with your therapist.', 2, null, 20, false),
  ('10000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000000002', '[DRAFT] Strengthen — standing band row', 'draft-strengthen-standing-band-row', 1, array['vb', 'xt']::text[], true, false, false, '{"section":2,"row":16,"col":2}'::jsonb, null, null, array['Clip the band at chest height and step back until it is lightly taut.', 'Draw both ends back toward your ribs, elbows close to your sides.', 'Return slowly over a count of three.']::text[], 'Before each set, check the band for nicks or tears and make sure the carabiner is closed on the anchor. Check the anchor is seated in the hexagon before you pull. Stop if you feel sharp pain, and check with your therapist.', 2, 10, null, false),
  ('10000000-0000-4000-8000-000000000006', '00000000-0000-4000-8000-000000000002', '[DRAFT] Strengthen — seated band row', 'draft-strengthen-seated-band-row', 1, array['vb', 'xt']::text[], true, false, true, '{"section":2,"row":6,"col":2}'::jsonb, null, null, array['Sit tall in a sturdy chair facing the board.', 'Clip the band at chest height when seated.', 'Draw both ends back toward your ribs, then return slowly.']::text[], 'Before each set, check the band for nicks or tears and make sure the carabiner is closed on the anchor. Check the anchor is seated in the hexagon before you pull. Stop if you feel sharp pain, and check with your therapist.', 2, 10, null, false),
  ('10000000-0000-4000-8000-000000000007', '00000000-0000-4000-8000-000000000005', '[DRAFT] Steady — heel-to-toe stand', 'draft-steady-heel-to-toe-stand', 1, array['vb', 'xt']::text[], false, true, false, '{"section":2,"row":8,"col":2}'::jsonb, null, null, array['Hold both rails.', 'Place one foot directly in front of the other.', 'Hold, then switch feet. Lighten your grip only when you feel ready.']::text[], 'Keep both hands on the rails until your therapist says otherwise. Check the rails are firmly attached before you start. Stop if you feel sharp pain, and check with your therapist.', 3, null, 20, false),
  ('10000000-0000-4000-8000-000000000008', '00000000-0000-4000-8000-000000000006', '[DRAFT] Rise — sit-to-stand with the rails', 'draft-rise-sit-to-stand-with-the-rails', 1, array['vb', 'xt']::text[], false, true, true, '{"section":2,"row":4,"col":2}'::jsonb, null, null, array['Set a sturdy chair in front of the board.', 'Hold the rails, lean forward slightly and stand up slowly.', 'Sit back down with control.']::text[], 'Use a chair that will not slide, and check the rails are firmly attached. Stop if you feel sharp pain, and check with your therapist.', 2, 8, null, false),
  ('10000000-0000-4000-8000-000000000009', '00000000-0000-4000-8000-000000000001', '[DRAFT] Climb — low wall walk', 'draft-climb-low-wall-walk', 1, array['vb', 'xt']::text[], false, false, false, '{"section":2,"row":16,"col":2}'::jsonb, null, null, array['Stand facing the board, feet hip-width apart.', 'Walk your fingers up to chest height, one hexagon at a time.', 'Walk them back down slowly.']::text[], 'Move slowly and stay within a comfortable range. Stop if you feel sharp pain, and check with your therapist.', 2, 8, 3, false),
  ('10000000-0000-4000-8000-000000000010', '00000000-0000-4000-8000-000000000005', '[DRAFT] Steady — feet-together stand', 'draft-steady-feet-together-stand', 1, array['vb', 'xt']::text[], false, true, false, '{"section":2,"row":8,"col":2}'::jsonb, null, null, array['Hold both rails.', 'Bring your feet together and stand tall.', 'Hold, breathing slowly.']::text[], 'Keep both hands on the rails. Check the rails are firmly attached before you start. Stop if you feel sharp pain, and check with your therapist.', 3, null, 20, false)
